enum class Priority : uint8_t {
    Critical = 0,
    High     = 1,
    Normal   = 2,
    Low      = 3,
    Count    = 4
};

class Task {
public:
    static constexpr size_t INLINE_STORAGE_BYTES = 48;

    using InvokeFn = void(*)(void*);
    using DestroyFn = void(*)(void*);

    constexpr Task() noexcept 
        : invoker_(nullptr), destroyer_(nullptr), priority_(Priority::Normal) {}

    template <typename F>
    requires (!std::is_same_v<std::decay_t<F>, Task> && 
              std::is_invocable_v<std::decay_t<F>> && 
              sizeof(std::decay_t<F>) <= INLINE_STORAGE_BYTES &&
              std::is_trivially_destructible_v<std::decay_t<F>>)
    Task(F&& callable, Priority prio = Priority::Normal) noexcept
        : priority_(prio) 
    {
        using DecayedF = std::decay_t<F>;
        new (storage_) DecayedF(std::forward<F>(callable));

        invoker_ = [](void* ptr) {
            (*reinterpret_cast<DecayedF*>(ptr))();
        };
        destroyer_ = nullptr; // Trivially destructible
    }

    template <typename F>
    requires (!std::is_same_v<std::decay_t<F>, Task> && 
              std::is_invocable_v<std::decay_t<F>> && 
              sizeof(std::decay_t<F>) <= INLINE_STORAGE_BYTES &&
              !std::is_trivially_destructible_v<std::decay_t<F>>)
    Task(F&& callable, Priority prio = Priority::Normal) noexcept
        : priority_(prio) 
    {
        using DecayedF = std::decay_t<F>;
        new (storage_) DecayedF(std::forward<F>(callable));

        invoker_ = [](void* ptr) {
            (*reinterpret_cast<DecayedF*>(ptr))();
        };
        destroyer_ = [](void* ptr) {
            reinterpret_cast<DecayedF*>(ptr)->~DecayedF();
        };
    }

    ~Task() {
        reset();
    }

    Task(Task&& other) noexcept 
        : invoker_(other.invoker_), 
          destroyer_(other.destroyer_), 
          priority_(other.priority_) 
    {
        std::memcpy(storage_, other.storage_, INLINE_STORAGE_BYTES);
        other.invoker_ = nullptr;
        other.destroyer_ = nullptr;
    }

    Task& operator=(Task&& other) noexcept {
        if (this != &other) {
            reset();
            invoker_ = other.invoker_;
            destroyer_ = other.destroyer_;
            priority_ = other.priority_;
            std::memcpy(storage_, other.storage_, INLINE_STORAGE_BYTES);
            other.invoker_ = nullptr;
            other.destroyer_ = nullptr;
        }
        return *this;
    }

    Task(const Task&) = delete;
    Task& operator=(const Task&) = delete;

    void operator()() {
        if (invoker_) {
            invoker_(storage_);
            reset();
        }
    }

    [[nodiscard]] explicit operator bool() const noexcept {
        return invoker_ != nullptr;
    }

    [[nodiscard]] Priority priority() const noexcept {
        return priority_;
    }

    void reset() noexcept {
        if (destroyer_) {
            destroyer_(storage_);
            destroyer_ = nullptr;
        }
        invoker_ = nullptr;
    }

private:
    alignas(std::max_align_t) std::byte storage_[INLINE_STORAGE_BYTES];
    InvokeFn invoker_{nullptr};
    DestroyFn destroyer_{nullptr};
    Priority priority_{Priority::Normal};
};

// ============================================================================
// NON-BLOCKING EPOCH-BASED RECLAMATION (EBR) WITH QUIESCENT DETACHMENT
// ============================================================================

class EpochManager {
public:
    static constexpr uint64_t EPOCH_MASK = 0x3; // 3 epochs: 0, 1, 2
    static constexpr size_t MAX_WORKERS = 256;
    static constexpr uint64_t INACTIVE_STATE = std::numeric_limits<uint64_t>::max();
    static constexpr size_t RETIRE_THRESHOLD = 64;

    struct RetiredNode {
        void* ptr{nullptr};
        void (*deleter)(void*){nullptr};
        RetiredNode* next{nullptr};
    };

    struct alignas(hardware_destructive_interference_size) LocalEpochToken {
        // Active epoch or INACTIVE_STATE if quiescent/asleep
        std::atomic<uint64_t> local_epoch{INACTIVE_STATE};

        // Circular retirement lists for 3 epochs (e, e-1, e-2)
        std::array<RetiredNode*, 3> retire_lists{nullptr, nullptr, nullptr};
        size_t retired_count{0};

        // Fast dynamic unregistration / thread metadata
        std::atomic<bool> is_registered{false};
        std::atomic<uint64_t> heartbeat{0};
    };

    EpochManager() : global_epoch_(0) {
        for (size_t i = 0; i < MAX_WORKERS; ++i) {
            tokens_[i].local_epoch.store(INACTIVE_STATE, std::memory_order_relaxed);
            tokens_[i].is_registered.store(false, std::memory_order_relaxed);
            tokens_[i].retired_count = 0;
            tokens_[i].retire_lists.fill(nullptr);
        }
    }

    ~EpochManager() {
        // Force cleanup of all lingering retired nodes on shutdown
        for (size_t i = 0; i < MAX_WORKERS; ++i) {
            for (size_t e = 0; e < 3; ++e) {
                reclaim_list(tokens_[i].retire_lists[e]);
                tokens_[i].retire_lists[e] = nullptr;
            }
        }
    }

    uint32_t register_thread() {
        for (uint32_t i = 0; i < MAX_WORKERS; ++i) {
            bool expected = false;
            if (tokens_[i].is_registered.compare_exchange_strong(
                    expected, true, 
                    std::memory_order_acq_rel, 
                    std::memory_order_relaxed)) 
            {
                tokens_[i].local_epoch.store(INACTIVE_STATE, std::memory_order_release);
                return i;
            }
        }
        throw std::runtime_error("EpochManager: Max registered threads exceeded.");
    }

    void unregister_thread(uint32_t worker_id) {
        if (worker_id >= MAX_WORKERS) return;

        // Mark quiescent first to never stall other advancing threads
        quiescent(worker_id);

        // Reclaim all thread-local queues by attempting epoch advancement
        for (size_t e = 0; e < 3; ++e) {
            reclaim_list(tokens_[worker_id].retire_lists[e]);
            tokens_[worker_id].retire_lists[e] = nullptr;
        }
        tokens_[worker_id].retired_count = 0;
        tokens_[worker_id].is_registered.store(false, std::memory_order_release);
    }

    // Enter critical section
    void enter(uint32_t worker_id) noexcept {
        // Read global epoch with relaxed ordering initially
        uint64_t current_global = global_epoch_.load(std::memory_order_relaxed);

        // Publish local epoch with acquire-release fence semantics
        // Synchronizes with try_advance_epoch scanning
        tokens_[worker_id].local_epoch.store(current_global, std::memory_order_release);
        std::atomic_thread_fence(std::memory_order_seq_cst);
        tokens_[worker_id].heartbeat.fetch_add(1, std::memory_order_relaxed);
    }

    // Leave critical section / signal Quiescent state
    void exit(uint32_t worker_id) noexcept {
        // Detach immediately: stall-free guarantee for external I/O or preemption
        tokens_[worker_id].local_epoch.store(INACTIVE_STATE, std::memory_order_release);
    }

    void quiescent(uint32_t worker_id) noexcept {
        exit(worker_id);
    }

    template <typename T>
    void retire(uint32_t worker_id, T* ptr) {
        if (!ptr) return;

        auto* node = new RetiredNode{
            .ptr = static_cast<void*>(ptr),
            .deleter = [](void* p) { delete static_cast<T*>(p); },
            .next = nullptr
        };

        uint64_t epoch = global_epoch_.load(std::memory_order_relaxed) % 3;
        node->next = tokens_[worker_id].retire_lists[epoch];
        tokens_[worker_id].retire_lists[epoch] = node;

        if (++tokens_[worker_id].retired_count >= RETIRE_THRESHOLD) {
            try_advance_epoch(worker_id);
        }
    }

    void try_advance_epoch(uint32_t worker_id) {
        uint64_t current = global_epoch_.load(std::memory_order_relaxed);

        // Ensure all registered threads have observed the epoch or are inactive
        for (size_t i = 0; i < MAX_WORKERS; ++i) {
            if (!tokens_[i].is_registered.load(std::memory_order_relaxed)) {
                continue;
            }

            uint64_t local = tokens_[i].local_epoch.load(std::memory_order_acquire);
            if (local != INACTIVE_STATE && local != current) {
                // Thread is still executing within an older epoch window; abort advancement
                return;
            }
        }

        // Try CAS to advance global epoch to current + 1
        if (global_epoch_.compare_exchange_strong(
                current, current + 1, 
                std::memory_order_acq_rel, 
                std::memory_order_relaxed)) 
        {
            // Successfully moved to current + 1. Reclaim items retired 2 epochs ago: (current + 1 - 2) % 3 = (current + 2) % 3
            uint64_t reclaim_epoch = (current + 2) % 3;
            reclaim_list(tokens_[worker_id].retire_lists[reclaim_epoch]);
            tokens_[worker_id].retire_lists[reclaim_epoch] = nullptr;
            tokens_[worker_id].retired_count = 0;
        }
    }

private:
    static void reclaim_list(RetiredNode* head) noexcept {
        while (head) {
            RetiredNode* next = head->next;
            head->deleter(head->ptr);
            delete head;
            head = next;
        }
    }

    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_;
    std::array<LocalEpochToken, MAX_WORKERS> tokens_;
};

// ============================================================================
// CHASE-LEV LOCK-FREE WORK-STEALING DEQUE (BOUNDED POWER-OF-TWO RING BUFFER)
// ============================================================================

template <typename T, size_t Capacity = 1024>
requires ((Capacity & (Capacity - 1)) == 0) // Must be power of 2
class WorkStealingDeque {
public:
    static constexpr size_t MASK = Capacity - 1;

    WorkStealingDeque() 
        : top_(0), bottom_(0) 
    {
        for (size_t i = 0; i < Capacity; ++i) {
            buffer_[i].store(nullptr, std::memory_order_relaxed);
        }
    }

    ~WorkStealingDeque() {
        int64_t b = bottom_.load(std::memory_order_relaxed);
        int64_t t = top_.load(std::memory_order_relaxed);
        for (int64_t i = t; i < b; ++i) {
            T* item = buffer_[i & MASK].load(std::memory_order_relaxed);
            delete item;
        }
    }

    WorkStealingDeque(const WorkStealingDeque&) = delete;
    WorkStealingDeque& operator=(const WorkStealingDeque&) = delete;

    // Push task onto bottom (Owner thread only)
    [[nodiscard]] bool push(T* item) noexcept {
        int64_t b = bottom_.load(std::memory_order_relaxed);
        // Acquire load top to avoid overwriting items being stolen
        int64_t t = top_.load(std::memory_order_acquire);

        if (b - t >= static_cast<int64_t>(Capacity)) {
            return false; // Queue full
        }

        buffer_[b & MASK].store(item, std::memory_order_relaxed);

        // Release ordering guarantees the slot write is visible prior to bottom increment
        bottom_.store(b + 1, std::memory_order_release);
        return true;
    }

    // Pop task from bottom (Owner thread only - LIFO)
    T* pop() noexcept {
        int64_t b = bottom_.load(std::memory_order_relaxed) - 1;
        bottom_.store(b, std::memory_order_relaxed);

        // Full memory barrier separating store to bottom from load of top
        // Critical for Dekker-style race resolution on weakly-ordered architectures
        std::atomic_thread_fence(std::memory_order_seq_cst);

        int64_t t = top_.load(std::memory_order_relaxed);

        if (t <= b) {
            // Non-empty deque
            if (t == b) {
                // Single element race condition: Contention between Owner and Thief
                T* item = buffer_[t & MASK].load(std::memory_order_relaxed);
                if (!top_.compare_exchange_strong(
                        t, t + 1, 
                        std::memory_order_seq_cst, 
                        std::memory_order_relaxed)) 
                {
                    // Thief won the race and stole the item
                    item = nullptr;
                }
                bottom_.store(b + 1, std::memory_order_relaxed);
                return item;
            } else {
                // More than 1 item available; no contention possible with thieves on bottom element
                T* item = buffer_[b & MASK].load(std::memory_order_relaxed);
                return item;
            }
        } else {
            // Queue is strictly empty
            bottom_.store(b + 1, std::memory_order_relaxed);
            return nullptr;
        }
    }

    // Steal task from top (Concurrent Thieves - FIFO)
    T* steal() noexcept {
        int64_t t = top_.load(std::memory_order_acquire);

        // Hardware fence enforcing visibility order of bottom vs top
        std::atomic_thread_fence(std::memory_order_seq_cst);

        int64_t b = bottom_.load(std::memory_order_acquire);

        if (t < b) {
            // Non-empty queue detected
            T* item = buffer_[t & MASK].load(std::memory_order_relaxed);

            // Acquire-Release CAS to synchronize with owner and concurrent thieves
            if (top_.compare_exchange_weak(
                    t, t + 1, 
                    std::memory_order_acq_rel, 
                    std::memory_order_relaxed)) 
            {
                return item;
            }
        }
        return nullptr;
    }

    [[nodiscard]] size_t size() const noexcept {
        int64_t b = bottom_.load(std::memory_order_relaxed);
        int64_t t = top_.load(std::memory_order_relaxed);
        return (b > t) ? static_cast<size_t>(b - t) : 0;
    }

    [[nodiscard]] bool empty() const noexcept {
        return size() == 0;
    }

private:
    // Padded to isolate cache lines and prevent destructive false sharing
    alignas(hardware_destructive_interference_size) std::atomic<int64_t> top_{0};
    alignas(hardware_destructive_interference_size) std::atomic<int64_t> bottom_{0};
    alignas(hardware_destructive_interference_size) std::array<std::atomic<T*>, Capacity> buffer_;
};

// ============================================================================
// MULTI-PRIORITY WORK-STEALING CONTAINER
// ============================================================================

template <size_t QueueCapacity = 1024>
class PriorityWorkStealingQueues {
public:
    static constexpr size_t NUM_PRIORITIES = static_cast<size_t>(Priority::Count);

    PriorityWorkStealingQueues() = default;

    bool push(Task* task) noexcept {
        if (!task) return false;
        size_t prio_idx = static_cast<size_t>(task->priority());
        return deques_[prio_idx].push(task);
    }

    Task* pop() noexcept {
        // Strict priority scheduling for owning worker (Critical -> Low)
        for (size_t i = 0; i < NUM_PRIORITIES; ++i) {
            Task* task = deques_[i].pop();
            if (task) return task;
        }
        return nullptr;
    }

    Task* steal() noexcept {
        // Thieves steal highest priority first to minimize latency of urgent tasks
        for (size_t i = 0; i < NUM_PRIORITIES; ++i) {
            Task* task = deques_[i].steal();
            if (task) return task;
        }
        return nullptr;
    }

    [[nodiscard]] size_t total_size() const noexcept {
        size_t total = 0;
        for (size_t i = 0; i < NUM_PRIORITIES; ++i) {
            total += deques_[i].size();
        }
        return total;
    }

private:
    std::array<WorkStealingDeque<Task, QueueCapacity>, NUM_PRIORITIES> deques_;
};

// ============================================================================
// NUMA TOPOLOGY & DOMAIN SPECIFICATION
// ============================================================================

struct NumaDomainInfo {
    uint32_t domain_id{0};
    std::vector<uint32_t> core_ids;
};

class NumaTopology {
public:
    static std::vector<NumaDomainInfo> detect_or_default(size_t worker_count) {
        std::vector<NumaDomainInfo> topology;

        // Group workers into 2 simulated NUMA domains if not configured
        size_t domains = (worker_count >= 8) ? 2 : 1;
        size_t workers_per_domain = (worker_count + domains - 1) / domains;

        for (size_t d = 0; d < domains; ++d) {
            NumaDomainInfo info;
            info.domain_id = static_cast<uint32_t>(d);
            for (size_t w = 0; w < workers_per_domain; ++w) {
                size_t id = d * workers_per_domain + w;
                if (id < worker_count) {
                    info.core_ids.push_back(static_cast<uint32_t>(id));
                }
            }
            if (!info.core_ids.empty()) {
                topology.push_back(std::move(info));
            }
        }
        return topology;
    }

    static void pin_thread_to_core([[maybe_unused]] uint32_t core_id) {
#if defined(__linux__)
        cpu_set_t cpuset;
        CPU_ZERO(&cpuset);
        CPU_SET(core_id, &cpuset);
        pthread_setaffinity_np(pthread_self(), sizeof(cpu_set_t), &cpuset);
#endif
    }
};

// ============================================================================
// NUMA-AWARE WORK-STEALING SCHEDULER
// ============================================================================

class Scheduler {
public:
    struct alignas(hardware_destructive_interference_size) WorkerState {
        uint32_t worker_id{0};
        uint32_t numa_domain{0};
        uint32_t core_id{0};
        PriorityWorkStealingQueues<1024> queues;

        // Fast PRNG state for Power-of-Two choice victim selection
        uint64_t rng_state{123456789};

        uint64_t fast_rand() noexcept {
            rng_state ^= (rng_state << 13);
            rng_state ^= (rng_state >> 7);
            rng_state ^= (rng_state << 17);
            return rng_state;
        }
    };

    explicit Scheduler(size_t worker_count = std::thread::hardware_concurrency())
        : num_workers_(std::max<size_t>(1, worker_count)),
          running_(false),
          workers_active_(0)
    {
        workers_ = std::make_unique<WorkerState[]>(num_workers_);
        auto topology = NumaTopology::detect_or_default(num_workers_);

        // Assign workers to NUMA domains and CPU cores
        for (const auto& domain : topology) {
            for (uint32_t core : domain.core_ids) {
                if (core < num_workers_) {
                    workers_[core].worker_id = core;
                    workers_[core].numa_domain = domain.domain_id;
                    workers_[core].core_id = core;
                    workers_[core].rng_state = 0x9E3779B97F4A7C15ULL * (core + 1);
                }
            }
        }

        // Cache intra-domain and inter-domain routing lists
        domain_workers_.resize(topology.size());
        for (size_t i = 0; i < num_workers_; ++i) {
            domain_workers_[workers_[i].numa_domain].push_back(static_cast<uint32_t>(i));
        }
    }

    ~Scheduler() {
        stop();
    }

    void start() {
        running_.store(true, std::memory_order_release);
        threads_.reserve(num_workers_);

        for (uint32_t i = 0; i < num_workers_; ++i) {
            threads_.emplace_back(&Scheduler::worker_loop, this, i);
        }

        // Wait for all workers to complete startup and registration
        while (workers_active_.load(std::memory_order_acquire) < num_workers_) {
            std::this_thread::yield();
        }
    }

    void stop() {
        if (!running_.exchange(false, std::memory_order_acq_rel)) {
            return;
        }

        // Wake all threads
        cv_wake_.notify_all();

        for (auto& t : threads_) {
            if (t.joinable()) {
                t.join();
            }
        }
        threads_.clear();
    }

    template <typename F>
    void schedule(F&& callable, Priority prio = Priority::Normal) {
        auto* task = new Task(std::forward<F>(callable), prio);

        // Fast path: Push to calling worker's queue if submitted from worker thread
        uint32_t wid = current_worker_id_;
        if (wid < num_workers_) {
            if (workers_[wid].queues.push(task)) {
                return;
            }
        }

        // Round-robin / random fallback injection for external threads
        uint32_t target = external_inject_idx_.fetch_add(1, std::memory_order_relaxed) % num_workers_;
        while (!workers_[target].queues.push(task)) {
            target = (target + 1) % num_workers_;
            std::this_thread::yield();
        }
    }

    [[nodiscard]] size_t worker_count() const noexcept {
        return num_workers_;
    }

private:
    static inline thread_local uint32_t current_worker_id_{std::numeric_limits<uint32_t>::max()};

    void worker_loop(uint32_t worker_id) {
        current_worker_id_ = worker_id;
        WorkerState& self = workers_[worker_id];

        NumaTopology::pin_thread_to_core(self.core_id);
        uint32_t ebr_token = epoch_mgr_.register_thread();

        workers_active_.fetch_add(1, std::memory_order_release);

        constexpr size_t MAX_SPIN_CYCLES = 32;
        constexpr size_t MAX_YIELDS = 16;
        size_t idle_count = 0;

        while (running_.load(std::memory_order_relaxed)) {
            // Signal Epoch Critical Section
            epoch_mgr_.enter(ebr_token);

            Task* task = self.queues.pop();

            if (!task) {
                task = steal_work(self);
            }

            if (task) {
                idle_count = 0;
                // Execute micro-task inside safe EBR epoch
                (*task)();

                // Safely retire the Task descriptor via EBR
                epoch_mgr_.retire(ebr_token, task);
                epoch_mgr_.exit(ebr_token);
            } else {
                // No work found: Quiesce and detach from epoch to allow other threads to reclaim memory
                epoch_mgr_.quiescent(ebr_token);

                if (idle_count < MAX_SPIN_CYCLES) {
#if defined(__x86_64__) || defined(_M_X64)
                    _mm_pause();
#elif defined(__aarch64__)
                    asm volatile("yield" ::: "memory");
#endif
                    ++idle_count;
                } else if (idle_count < MAX_SPIN_CYCLES + MAX_YIELDS) {
                    std::this_thread::yield();
                    ++idle_count;
                } else {
                    // Back off with short sleep under depleted workloads
                    std::unique_lock<std::mutex> lock(sleep_mtx_);
                    cv_wake_.wait_for(lock, std::chrono::microseconds(50), [this]() {
                        return !running_.load(std::memory_order_relaxed);
                    });
                }
            }
        }

        epoch_mgr_.unregister_thread(ebr_token);
    }

    Task* steal_work(WorkerState& self) noexcept {
        const auto& local_domain = domain_workers_[self.numa_domain];
        size_t domain_size = local_domain.size();

        // 1. Intra-NUMA Stealing: Hierarchical Power-of-Two choices
        if (domain_size > 1) {
            uint32_t v1 = local_domain[self.fast_rand() % domain_size];
            uint32_t v2 = local_domain[self.fast_rand() % domain_size];

            // Avoid self
            if (v1 != self.worker_id) {
                if (Task* task = workers_[v1].queues.steal()) return task;
            }
            if (v2 != self.worker_id && v2 != v1) {
                if (Task* task = workers_[v2].queues.steal()) return task;
            }
        }

        // 2. Inter-NUMA Cross-Domain Stealing: Biased sampling fallback
        if (domain_workers_.size() > 1) {
            size_t remote_domain_idx = self.fast_rand() % domain_workers_.size();
            if (remote_domain_idx != self.numa_domain) {
                const auto& remote_domain = domain_workers_[remote_domain_idx];
                if (!remote_domain.empty()) {
                    uint32_t victim = remote_domain[self.fast_rand() % remote_domain.size()];
                    if (Task* task = workers_[victim].queues.steal()) {
                        return task;
                    }
                }
            }
        }

        return nullptr;
    }

    size_t num_workers_;
    std::atomic<bool> running_{false};
    std::atomic<size_t> workers_active_{0};
    std::atomic<uint32_t> external_inject_idx_{0};

    std::unique_ptr<WorkerState[]> workers_;
    std::vector<std::vector<uint32_t>> domain_workers_;
    std::vector<std::thread> threads_;

    EpochManager epoch_mgr_;

    std::mutex sleep_mtx_;
    std::condition_variable cv_wake_;
};

