```cpp
#include <iostream>
#include <atomic>
#include <thread>
#include <vector>
#include <memory>
#include <optional>
#include <functional>
#include <array>
#include <chrono>
#include <random>
#include <cassert>
#include <cstdint>
#include <cstring>
#include <new>

#if defined(__linux__)
#include <sched.h>
#include <pthread.h>
#endif

// ============================================================================
// Cache-Line & Hardware Interference Alignment
// ============================================================================
#ifdef __cpp_lib_hardware_interference_size
    using std::hardware_destructive_interference_size;
    using std::hardware_constructive_interference_size;
#else
    // Standard L1 cache line size fallback for x86-64 and AArch64
    constexpr size_t hardware_destructive_interference_size = 64;
    constexpr size_t hardware_constructive_interference_size = 64;
#endif

// ============================================================================
// Core Data Types & Task Descriptors
// ============================================================================

enum class Priority : uint8_t {
    Critical = 0,
    High     = 1,
    Normal   = 2,
    Low      = 3,
    Count    = 4
};

/// Fixed-size inline task functor to eliminate dynamic heap allocations
class Task {
public:
    using InvokerFn = void(*)(void*);

    constexpr Task() noexcept : invoker_(nullptr) {}

    template <typename F>
    Task(F&& callable) {
        static_assert(sizeof(F) <= STORAGE_SIZE, "Callable exceeds inline storage size");
        static_assert(alignof(F) <= alignof(std::max_align_t), "Callable alignment too large");

        using DecayedF = std::decay_t<F>;
        new (storage_) DecayedF(std::forward<F>(callable));

        invoker_ = [](void* ptr) {
            auto& obj = *reinterpret_cast<DecayedF*>(ptr);
            obj();
            obj.~DecayedF();
        };
    }

    Task(Task&& other) noexcept : invoker_(other.invoker_) {
        std::memcpy(storage_, other.storage_, STORAGE_SIZE);
        other.invoker_ = nullptr;
    }

    Task& operator=(Task&& other) noexcept {
        if (this != &other) {
            reset();
            invoker_ = other.invoker_;
            std::memcpy(storage_, other.storage_, STORAGE_SIZE);
            other.invoker_ = nullptr;
        }
        return *this;
    }

    Task(const Task&) = delete;
    Task& operator=(const Task&) = delete;

    ~Task() {
        reset();
    }

    void operator()() {
        if (invoker_) {
            InvokerFn call = invoker_;
            invoker_ = nullptr;
            call(storage_);
        }
    }

    explicit operator bool() const noexcept {
        return invoker_ != nullptr;
    }

    void reset() noexcept {
        if (invoker_) {
            // Discard without invoking
            invoker_ = nullptr;
        }
    }

private:
    static constexpr size_t STORAGE_SIZE = 48;
    alignas(std::max_align_t) char storage_[STORAGE_SIZE];
    InvokerFn invoker_;
};

// ============================================================================
// Epoch-Based Memory Reclamation (EBR) with Quiescent State / Heartbeat Tracking
// ============================================================================

class EpochManager {
public:
    static constexpr uint64_t EPOCH_MASK = 3;
    static constexpr uint64_t INACTIVE_EPOCH = std::numeric_limits<uint64_t>::max();
    static constexpr uint64_t STALL_THRESHOLD_MS = 50;

    struct alignas(hardware_destructive_interference_size) ThreadControlBlock {
        std::atomic<uint64_t> local_epoch{INACTIVE_EPOCH};
        std::atomic<uint64_t> last_heartbeat{0};
        std::atomic<bool>     is_active{false};
        std::atomic<bool>     is_stalled{false};
        ThreadControlBlock*   next{nullptr};
    };

    struct RetiredNode {
        void* data{nullptr};
        void (*deleter)(void*){nullptr};
        RetiredNode* next{nullptr};
    };

    EpochManager() : global_epoch_(0), registry_head_(nullptr) {}

    ~EpochManager() {
        // Drain all garbage lists unconditionally on shutdown
        for (size_t e = 0; e < 3; ++e) {
            RetiredNode* curr = retired_lists_[e].exchange(nullptr, std::memory_order_relaxed);
            while (curr) {
                RetiredNode* next = curr->next;
                if (curr->deleter && curr->data) {
                    curr->deleter(curr->data);
                }
                delete curr;
                curr = next;
            }
        }
    }

    void register_thread(ThreadControlBlock& tcb) {
        tcb.is_active.store(true, std::memory_order_relaxed);
        tcb.last_heartbeat.store(get_time_ms(), std::memory_order_relaxed);

        ThreadControlBlock* old_head = registry_head_.load(std::memory_order_relaxed);
        do {
            tcb.next = old_head;
            // acquire/release ensures registration is safely published
        } while (!registry_head_.compare_exchange_weak(old_head, &tcb,
                                                       std::memory_order_acq_rel,
                                                       std::memory_order_relaxed));
    }

    void unregister_thread(ThreadControlBlock& tcb) {
        tcb.local_epoch.store(INACTIVE_EPOCH, std::memory_order_release);
        tcb.is_active.store(false, std::memory_order_release);
    }

    void enter_quiescent_region(ThreadControlBlock& tcb) noexcept {
        uint64_t g_epoch = global_epoch_.load(std::memory_order_acquire);
        tcb.local_epoch.store(g_epoch, std::memory_order_release);
        tcb.last_heartbeat.store(get_time_ms(), std::memory_order_relaxed);
    }

    void exit_quiescent_region(ThreadControlBlock& tcb) noexcept {
        // Exiting the critical region sets the local epoch to inactive
        tcb.local_epoch.store(INACTIVE_EPOCH, std::memory_order_release);
    }

    template <typename T>
    void retire(T* ptr) {
        if (!ptr) return;
        auto* node = new RetiredNode();
        node->data = ptr;
        node->deleter = [](void* p) { delete static_cast<T*>(p); };

        uint64_t g_epoch = global_epoch_.load(std::memory_order_relaxed) % 3;

        RetiredNode* old_head = retired_lists_[g_epoch].load(std::memory_order_relaxed);
        do {
            node->next = old_head;
        } while (!retired_lists_[g_epoch].compare_exchange_weak(old_head, node,
                                                                std::memory_order_acq_rel,
                                                                std::memory_order_relaxed));
    }

    /// Try advancing global epoch and reclaim safe garbage generations
    void try_advance_epoch() {
        uint64_t current_g_epoch = global_epoch_.load(std::memory_order_acquire);
        uint64_t now = get_time_ms();

        // Check if all active non-stalled threads have reached the current global epoch
        ThreadControlBlock* curr = registry_head_.load(std::memory_order_acquire);
        while (curr) {
            if (curr->is_active.load(std::memory_order_acquire)) {
                uint64_t th_epoch = curr->local_epoch.load(std::memory_order_acquire);
                uint64_t hb = curr->last_heartbeat.load(std::memory_order_relaxed);

                // Check for stalled thread phenomenon
                if (th_epoch != INACTIVE_EPOCH && th_epoch != current_g_epoch) {
                    if (now - hb > STALL_THRESHOLD_MS) {
                        // Mark stalled to prevent unbounded memory bloat
                        curr->is_stalled.store(true, std::memory_order_release);
                    } else {
                        // Thread is active and legitimately in an older epoch: cannot advance
                        return;
                    }
                } else {
                    curr->is_stalled.store(false, std::memory_order_relaxed);
                }
            }
            curr = curr->next;
        }

        // Advance global epoch by 1
        if (global_epoch_.compare_exchange_strong(current_g_epoch, current_g_epoch + 1,
                                                  std::memory_order_acq_rel,
                                                  std::memory_order_relaxed)) {
            // Reclaim retired items from (current_g_epoch - 2)
            // Ring arithmetic modulo 3: (e + 1) % 3 corresponds to the safe retired list
            size_t safe_epoch_idx = (current_g_epoch + 1) % 3;
            RetiredNode* reclaim_list = retired_lists_[safe_epoch_idx].exchange(nullptr, std::memory_order_acq_rel);

            while (reclaim_list) {
                RetiredNode* next = reclaim_list->next;
                if (reclaim_list->deleter && reclaim_list->data) {
                    reclaim_list->deleter(reclaim_list->data);
                }
                delete reclaim_list;
                reclaim_list = next;
            }
        }
    }

private:
    static uint64_t get_time_ms() noexcept {
        return static_cast<uint64_t>(
            std::chrono::duration_cast<std::chrono::milliseconds>(
                std::chrono::steady_clock::now().time_since_epoch()
            ).count()
        );
    }

    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_;
    alignas(hardware_destructive_interference_size) std::atomic<ThreadControlBlock*> registry_head_;
    alignas(hardware_destructive_interference_size) std::array<std::atomic<RetiredNode*>, 3> retired_lists_{};
};

// ============================================================================
// Lock-Free Chase-Lev Work-Stealing Ring Buffer Deque
// ============================================================================

template <typename T, size_t Capacity = 1024>
class WorkStealingDeque {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of 2");

public:
    WorkStealingDeque() : top_(0), bottom_(0) {
        for (size_t i = 0; i < Capacity; ++i) {
            buffer_[i].store(nullptr, std::memory_order_relaxed);
        }
    }

    ~WorkStealingDeque() {
        int64_t b = bottom_.load(std::memory_order_relaxed);
        int64_t t = top_.load(std::memory_order_relaxed);
        for (int64_t i = t; i < b; ++i) {
            T* item = buffer_[i & BUFFER_MASK].load(std::memory_order_relaxed);
            delete item;
        }
    }

    // PUSH (Owner thread only: LIFO bottom)
    bool push(T* item) noexcept {
        int64_t b = bottom_.load(std::memory_order_relaxed);
        int64_t t = top_.load(std::memory_order_acquire); // Synchronizes with thief's CAS

        if (b - t >= static_cast<int64_t>(Capacity)) {
            return false; // Queue full
        }

        buffer_[b & BUFFER_MASK].store(item, std::memory_order_relaxed);

        // Release store ensures the item payload is visible before bottom increments
        bottom_.store(b + 1, std::memory_order_release);
        return true;
    }

    // POP (Owner thread only: LIFO bottom)
    T* pop() noexcept {
        int64_t b = bottom_.load(std::memory_order_relaxed) - 1;
        bottom_.store(b, std::memory_order_relaxed);

        // Enforce sequential consistency fence between bottom store and top load
        // preventing load-load / store-load reordering on weakly-ordered CPUs (ARMv8/POWER)
        std::atomic_thread_fence(std::memory_order_seq_cst);

        int64_t t = top_.load(std::memory_order_relaxed);

        if (t <= b) {
            // Non-empty deque
            if (t == b) {
                // Exactly 1 element race: Pop races against concurrent Steal
                if (!top_.compare_exchange_strong(t, t + 1, 
                                                   std::memory_order_seq_cst, 
                                                   std::memory_order_relaxed)) {
                    // Thief won the race: reset bottom to empty state
                    bottom_.store(b + 1, std::memory_order_relaxed);
                    return nullptr;
                }
                // Owner won the race
                bottom_.store(b + 1, std::memory_order_relaxed);
                return buffer_[b & BUFFER_MASK].load(std::memory_order_relaxed);
            }

            // More than 1 item remains: safely retrieve item
            return buffer_[b & BUFFER_MASK].load(std::memory_order_relaxed);
        } else {
            // Deque was already empty: restore bottom
            bottom_.store(b + 1, std::memory_order_relaxed);
            return nullptr;
        }
    }

    // STEAL (Thief threads: FIFO top)
    enum class StealResult { Success, Empty, Abort };

    std::pair<StealResult, T*> steal() noexcept {
        int64_t t = top_.load(std::memory_order_acquire);
        std::atomic_thread_fence(std::memory_order_seq_cst);
        int64_t b = bottom_.load(std::memory_order_acquire);

        if (t >= b) {
            return {StealResult::Empty, nullptr};
        }

        T* item = buffer_[t & BUFFER_MASK].load(std::memory_order_relaxed);

        // Compete for the element at index t
        if (top_.compare_exchange_weak(t, t + 1,
                                       std::memory_order_seq_cst,
                                       std::memory_order_relaxed)) {
            return {StealResult::Success, item};
        }

        return {StealResult::Abort, nullptr};
    }

    [[nodiscard]] size_t size_approx() const noexcept {
        int64_t b = bottom_.load(std::memory_order_relaxed);
        int64_t t = top_.load(std::memory_order_relaxed);
        return b > t ? static_cast<size_t>(b - t) : 0;
    }

private:
    static constexpr size_t BUFFER_MASK = Capacity - 1;

    // Cache-line separated atomic indices to prevent false sharing between Owner and Thieves
    alignas(hardware_destructive_interference_size) std::atomic<int64_t> top_;
    alignas(hardware_destructive_interference_size) std::atomic<int64_t> bottom_;
    alignas(hardware_destructive_interference_size) std::array<std::atomic<T*>, Capacity> buffer_;
};

// ============================================================================
// Priority Multi-Tier Work-Stealing Structure
// ============================================================================

template <size_t CapacityPerTier = 1024>
class PriorityWorkStealingDeque {
public:
    bool push(Task&& task, Priority priority) {
        auto* descriptor = new Task(std::move(task));
        auto tier = static_cast<size_t>(priority);

        if (!queues_[tier].push(descriptor)) {
            delete descriptor; // Queue overflow
            return false;
        }
        return true;
    }

    std::optional<Task> pop() {
        // Owner pops in strict priority order (Critical -> High -> Normal -> Low)
        for (size_t i = 0; i < static_cast<size_t>(Priority::Count); ++i) {
            Task* desc = queues_[i].pop();
            if (desc) {
                Task local_task = std::move(*desc);
                delete desc;
                return local_task;
            }
        }
        return std::nullopt;
    }

    std::optional<Task> steal(Priority max_priority = Priority::Low) {
        // Thief steals highest available priority tier up to max_priority
        size_t max_tier = static_cast<size_t>(max_priority);
        for (size_t i = 0; i <= max_tier; ++i) {
            auto [result, desc] = queues_[i].steal();
            if (result == WorkStealingDeque<Task, CapacityPerTier>::StealResult::Success && desc) {
                Task local_task = std::move(*desc);
                delete desc;
                return local_task;
            }
        }
        return std::nullopt;
    }

    [[nodiscard]] size_t load_approx() const noexcept {
        size_t total = 0;
        for (size_t i = 0; i < static_cast<size_t>(Priority::Count); ++i) {
            total += queues_[i].size_approx();
        }
        return total;
    }

private:
    std::array<WorkStealingDeque<Task, CapacityPerTier>, static_cast<size_t>(Priority::Count)> queues_;
};

// ============================================================================
// NUMA Topology & Thread Affinity Management
// ============================================================================

struct NUMATopology {
    size_t numa_nodes{1};
    size_t cores_per_node{4};
    size_t total_workers{4};

    static NUMATopology detect_or_default() {
        NUMATopology topo;
        unsigned int hardware_threads = std::thread::hardware_concurrency();
        if (hardware_threads == 0) hardware_threads = 4;

        // Default heuristic: 2 NUMA domains if >= 8 threads, otherwise single domain
        if (hardware_threads >= 8) {
            topo.numa_nodes = 2;
            topo.cores_per_node = hardware_threads / 2;
        } else {
            topo.numa_nodes = 1;
            topo.cores_per_node = hardware_threads;
        }
        topo.total_workers = topo.numa_nodes * topo.cores_per_node;
        return topo;
    }
};

inline void bind_thread_to_core(size_t core_id) {
#if defined(__linux__)
    cpu_set_t cpuset;
    CPU_ZERO(&cpuset);
    CPU_SET(core_id, &cpuset);
    pthread_setaffinity_np(pthread_self(), sizeof(cpu_set_t), &cpuset);
#else
    (void)core_id;
#endif
}

// ============================================================================
// NUMA-Aware Multi-Producer Multi-Consumer (MPMC) Work-Stealing Scheduler
// ============================================================================

class Scheduler {
public:
    struct alignas(hardware_destructive_interference_size) WorkerContext {
        size_t id{0};
        size_t numa_node_id{0};
        PriorityWorkStealingDeque<1024> deque;
        EpochManager::ThreadControlBlock tcb;
        std::atomic<uint64_t> tasks_executed{0};
        std::atomic<uint64_t> tasks_stolen_local{0};
        std::atomic<uint64_t> tasks_stolen_remote{0};
        std::minstd_rand rng;
    };

    explicit Scheduler(NUMATopology topo = NUMATopology::detect_or_default())
        : topo_(topo), running_(false) {
        workers_.reserve(topo_.total_workers);

        for (size_t i = 0; i < topo_.total_workers; ++i) {
            auto worker = std::make_unique<WorkerContext>();
            worker->id = i;
            worker->numa_node_id = i / topo_.cores_per_node;
            worker->rng.seed(1337 + static_cast<uint32_t>(i) * 101);
            workers_.push_back(std::move(worker));
        }
    }

    ~Scheduler() {
        stop();
    }

    void start() {
        running_.store(true, std::memory_order_release);
        threads_.reserve(topo_.total_workers);

        for (size_t i = 0; i < topo_.total_workers; ++i) {
            threads_.emplace_back(&Scheduler::worker_loop, this, i);
        }
    }

    void stop() {
        if (running_.exchange(false, std::memory_order_acq_rel)) {
            for (auto& th : threads_) {
                if (th.joinable()) {
                    th.join();
                }
            }
            threads_.clear();
        }
    }

    /// Submit a task directly to an appropriate NUMA node / worker
    void submit(Task&& task, Priority priority = Priority::Normal, std::optional<size_t> preferred_numa_node = std::nullopt) {
        size_t target_node = preferred_numa_node.value_or(0) % topo_.numa_nodes;
        size_t start_idx = target_node * topo_.cores_per_node;
        size_t end_idx = start_idx + topo_.cores_per_node;

        // Find least-loaded worker in the target NUMA domain
        size_t best_worker = start_idx;
        size_t min_load = std::numeric_limits<size_t>::max();

        for (size_t i = start_idx; i < end_idx; ++i) {
            size_t load = workers_[i]->deque.load_approx();
            if (load < min_load) {
                min_load = load;
                best_worker = i;
            }
        }

        while (!workers_[best_worker]->deque.push(std::move(task), priority)) {
            // Backoff on overflow and fallback to next adjacent core
            best_worker = start_idx + ((best_worker - start_idx + 1) % topo_.cores_per_node);
            std::this_thread::yield();
        }
    }

    void print_telemetry() const {
        std::cout << "\n================ Execution Telemetry ================\n";
        uint64_t total_exec = 0, total_local_stolen = 0, total_remote_stolen = 0;
        for (const auto& w : workers_) {
            uint64_t exec = w->tasks_executed.load(std::memory_order_relaxed);
            uint64_t l_stolen = w->tasks_stolen_local.load(std::memory_order_relaxed);
            uint64_t r_stolen = w->tasks_stolen_remote.load(std::memory_order_relaxed);
            total_exec += exec;
            total_local_stolen += l_stolen;
            total_remote_stolen += r_stolen;

            std::cout << "Worker [" << w->id << "] (NUMA " << w->numa_node_id << "): "
                      << "Executed=" << exec << " | "
                      << "Local Stolen=" << l_stolen << " | "
                      << "Remote Stolen=" << r_stolen << "\n";
        }
        std::cout << "-----------------------------------------------------\n";
        std::cout << "Total Tasks Executed:       " << total_exec << "\n";
        std::cout << "Total Intra-NUMA Steals:    " << total_local_stolen << "\n";
        std::cout << "Total Cross-NUMA Steals:    " << total_remote_stolen << "\n";
        std::cout << "=====================================================\n\n";
    }

private:
    void worker_loop(size_t worker_id) {
        WorkerContext& self = *workers_[worker_id];
        bind_thread_to_core(worker_id);
        epoch_manager_.register_thread(self.tcb);

        size_t consecutive_idle_cycles = 0;

        while (running_.load(std::memory_order_relaxed)) {
            epoch_manager_.enter_quiescent_region(self.tcb);

            // Step 1: Owner LIFO pop from local priority deque
            std::optional<Task> task = self.deque.pop();

            // Step 2: Intra-NUMA Stealing via Power-of-Two-Choices (FIFO)
            if (!task) {
                task = try_steal_local_numa(self);
                if (task) {
                    self.tasks_stolen_local.fetch_add(1, std::memory_order_relaxed);
                }
            }

            // Step 3: Cross-NUMA Stealing (Critical & High Priorities only)
            if (!task && (consecutive_idle_cycles > 16)) {
                task = try_steal_remote_numa(self);
                if (task) {
                    self.tasks_stolen_remote.fetch_add(1, std::memory_order_relaxed);
                }
            }

            // Step 4: Execute or Exponential Backoff
            if (task) {
                consecutive_idle_cycles = 0;
                (*task)();
                self.tasks_executed.fetch_add(1, std::memory_order_relaxed);
            } else {
                ++consecutive_idle_cycles;
                if (consecutive_idle_cycles > 64) {
                    std::this_thread::yield();
                }
            }

            epoch_manager_.exit_quiescent_region(self.tcb);

            // Periodic EBR advancement check
            if ((worker_id == 0) && (consecutive_idle_cycles % 128 == 0)) {
                epoch_manager_.try_advance_epoch();
            }
        }

        epoch_manager_.unregister_thread(self.tcb);
    }

    std::optional<Task> try_steal_local_numa(WorkerContext& self) {
        size_t start_idx = self.numa_node_id * topo_.cores_per_node;
        size_t count = topo_.cores_per_node;
        if (count <= 1) return std::nullopt;

        // Sample two random distinct victims in local NUMA domain (Power-of-Two-Choices)
        size_t v1 = start_idx + (self.rng() % count);
        size_t v2 = start_idx + (self.rng() % count);
        while (v1 == self.id) v1 = start_idx + (self.rng() % count);
        while (v2 == self.id || v2 == v1) v2 = start_idx + (self.rng() % count);

        size_t target = (workers_[v1]->deque.load_approx() >= workers_[v2]->deque.load_approx()) ? v1 : v2;
        return workers_[target]->deque.steal(Priority::Low);
    }

    std::optional<Task> try_steal_remote_numa(WorkerContext& self) {
        if (topo_.numa_nodes <= 1) return std::nullopt;

        // Select a remote NUMA node randomly
        size_t remote_node = (self.numa_node_id + 1 + (self.rng() % (topo_.numa_nodes - 1))) % topo_.numa_nodes;
        size_t start_idx = remote_node * topo_.cores_per_node;
        size_t victim_idx = start_idx + (self.rng() % topo_.cores_per_node);

        // Restrict remote stealing to Critical/High to protect interconnect bandwidth
        return workers_[victim_idx]->deque.steal(Priority::High);
    }

    NUMATopology topo_;
    std::atomic<bool> running_{false};
    EpochManager epoch_manager_;
    std::vector<std::unique_ptr<WorkerContext>> workers_;
    std::vector<std::thread> threads_;
};

// ============================================================================
// Verification & Micro-Benchmark Entry Point
// ============================================================================

int main() {
    std::cout << "Initializing NUMA-Aware Work-Stealing Compute Runtime...\n";

    NUMATopology topo = NUMATopology::detect_or_default();
    std::cout << "Topology Configured: " << topo.numa_nodes << " NUMA Nodes, "
              << topo.cores_per_node << " Cores/Node (" << topo.total_workers << " Workers Total).\n";

    Scheduler scheduler(topo);
