    for (size_t i = 0; i < TOTAL_TASKS; ++i) {
        Priority p;
        if (i % 100 == 0)      p = Priority::Critical;
        else if (i % 20 == 0) p = Priority::High;
        else if (i % 4 == 0)  p = Priority::Normal;
        else                  p = Priority::Low;

        // Submitting only to NUMA Node 0 to trigger heavy load-balancing and work stealing
        scheduler.submit([&tasks_completed]() {
