### Part 1: Memory Layout & Lock-Free MVCC Data Structures

```cpp
#pragma once

#include <atomic>
#include <cstdint>
#include <cstddef>
#include <cstring>
#include <array>
#include <memory>
#include <vector>
#include <optional>
#include <immintrin.h>
#include <new>

namespace mvcc {

static constexpr size_t CACHE_LINE_SIZE = 64;
static constexpr size_t MAX_SKIPLIST_LEVEL = 16;
static constexpr uint64_t TX_UNCOMMITTED = 0;
static constexpr uint64_t TX_ABORTED = UINT64_MAX;
static constexpr uint64_t TOMBSTONE_FLAG = 1ULL << 63;
static constexpr uint64_t TS_MASK = ~TOMBSTONE_FLAG;

// Tagged pointer representation to mitigate ABA in multi-link operations
template <typename T>
struct alignas(CACHE_LINE_SIZE) TaggedAtomicPtr {
    struct TaggedPtr {
        T* ptr;
        uintptr_t tag;
    };

    std::atomic<TaggedPtr> atomic_ptr;

    TaggedAtomicPtr() noexcept : atomic_ptr(TaggedPtr{nullptr, 0}) {}
    explicit TaggedAtomicPtr(T* p, uintptr_t t = 0) noexcept : atomic_ptr(TaggedPtr{p, t}) {}

    TaggedPtr load(std::memory_order order = std::memory_order_seq_cst) const noexcept {
        return atomic_ptr.load(order);
    }

    void store(T* p, uintptr_t t, std::memory_order order = std::memory_order_seq_cst) noexcept {
        atomic_ptr.store(TaggedPtr{p, t}, order);
    }

    bool compare_exchange_weak(TaggedPtr& expected, TaggedPtr desired,
                               std::memory_order success, std::memory_order failure) noexcept {
        return atomic_ptr.compare_exchange_weak(expected, desired, success, failure);
    }
};

// MVCC Version Node: Descending version chain per key
struct alignas(CACHE_LINE_SIZE) VersionNode {
    uint64_t tx_id;                          // Transaction ID creating this version
    std::atomic<uint64_t> commit_ts;         // TX_UNCOMMITTED, TX_ABORTED, or commit timestamp (bit 63 = tombstone)
    const char* value_data;                  // Read-only payload
    uint32_t value_len;                      // Payload length
    std::atomic<VersionNode*> next_version;  // Pointer down the historical chain
    uint64_t epoch_retired;                  // Quarantine tag for EBR

    VersionNode(uint64_t tid, const char* val, uint32_t len, VersionNode* next = nullptr, bool is_tombstone = false)
        : tx_id(tid),
          commit_ts(TX_UNCOMMITTED | (is_tombstone ? TOMBSTONE_FLAG : 0)),
          value_len(len),
          next_version(next),
          epoch_retired(0) {
        if (val && len > 0) {
            char* buf = new char[len];
            std::memcpy(buf, val, len);
            value_data = buf;
        } else {
            value_data = nullptr;
        }
    }

    ~VersionNode() {
        if (value_data) {
            delete[] value_data;
            value_data = nullptr;
        }
    }

    [[nodiscard]] bool is_deleted() const noexcept {
        return (commit_ts.load(std::memory_order_relaxed) & TOMBSTONE_FLAG) != 0;
    }

    [[nodiscard]] uint64_t get_raw_ts() const noexcept {
        return commit_ts.load(std::memory_order_acquire) & TS_MASK;
    }
};

// Logical marked pointer for Skip-List node deletion
template <typename T>
inline bool is_marked(T* ptr) noexcept {
    return (reinterpret_cast<uintptr_t>(ptr) & 1ULL) != 0;
}

template <typename T>
inline T* get_unmarked(T* ptr) noexcept {
    return reinterpret_cast<T*>(reinterpret_cast<uintptr_t>(ptr) & ~1ULL);
}

template <typename T>
inline T* get_marked(T* ptr) noexcept {
    return reinterpret_cast<T*>(reinterpret_cast<uintptr_t>(ptr) | 1ULL);
}

// Skip-List Node
struct alignas(CACHE_LINE_SIZE) SkipListNode {
    uint64_t key;
    size_t height;
    std::atomic<VersionNode*> version_chain_head;
    std::atomic<SkipListNode*> forward[MAX_SKIPLIST_LEVEL];

    SkipListNode(uint64_t k, size_t h, VersionNode* initial_version)
        : key(k), height(h), version_chain_head(initial_version) {
        for (size_t i = 0; i < MAX_SKIPLIST_LEVEL; ++i) {
            forward[i].store(nullptr, std::memory_order_relaxed);
        }
    }
};

} // namespace mvcc
