### Part 2: Epoch-Based Reclamation with Hazard Fallback

```cpp
namespace mvcc {

static constexpr size_t MAX_THREADS = 256;
static constexpr uint64_t EPOCH_PIN_TIMEOUT_CYCLES = 50'000'000; // ~15-20ms bound

struct alignas(CACHE_LINE_SIZE) ThreadEpochState {
    std::atomic<uint64_t> local_epoch{0};
    std::atomic<bool> active{false};
    std::atomic<uint64_t> enter_timestamp{0};
    std::atomic<const void*> hazard_ptr{nullptr}; // Emergency fallback for long operations
    char pad[CACHE_LINE_SIZE - sizeof(std::atomic<uint64_t>) * 2 - sizeof(std::atomic<bool>) - sizeof(std::atomic<void*>)];
};

class AdaptiveEpochManager {
public:
    static AdaptiveEpochManager& instance() {
        static AdaptiveEpochManager mgr;
        return mgr;
    }

    void register_thread(size_t tid) {
        thread_states_[tid].active.store(true, std::memory_order_release);
    }

    void unregister_thread(size_t tid) {
        thread_states_[tid].active.store(false, std::memory_order_release);
        thread_states_[tid].hazard_ptr.store(nullptr, std::memory_order_release);
    }

    // Critical section entry: Wait-free O(1)
    void enter_read(size_t tid) noexcept {
        thread_states_[tid].local_epoch.store(global_epoch_.load(std::memory_order_relaxed), std::memory_order_relaxed);
        thread_states_[tid].enter_timestamp.store(__rdtsc(), std::memory_order_relaxed);
        thread_states_[tid].active.store(true, std::memory_order_release);
        std::atomic_thread_fence(std::memory_order_seq_cst);
    }

    // Critical section exit: Wait-free O(1)
    void exit_read(size_t tid) noexcept {
        thread_states_[tid].hazard_ptr.store(nullptr, std::memory_order_relaxed);
        thread_states_[tid].active.store(false, std::memory_order_release);
    }

    void set_hazard(size_t tid, const void* ptr) noexcept {
        thread_states_[tid].hazard_ptr.store(ptr, std::memory_order_release);
    }

    void clear_hazard(size_t tid) noexcept {
        thread_states_[tid].hazard_ptr.store(nullptr, std::memory_order_release);
    }

    // Quarantines a node into the retired bag of current epoch
    void retire_node(VersionNode* node, size_t tid) {
        uint64_t e = global_epoch_.load(std::memory_order_relaxed);
        node->epoch_retired = e;
        retired_bags_[tid][e % 3].push_back(node);

        // Periodically attempt advancement
        if (retired_bags_[tid][e % 3].size() > 64) {
            try_advance_epoch();
            reclaim_quarantine(tid);
        }
    }

    void try_advance_epoch() {
        uint64_t cur = global_epoch_.load(std::memory_order_relaxed);
        uint64_t now = __rdtsc();

        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (!thread_states_[i].active.load(std::memory_order_acquire)) {
                continue;
            }
            uint64_t t_epoch = thread_states_[i].local_epoch.load(std::memory_order_acquire);
            if (t_epoch < cur) {
                // Check if the thread has stalled past the threshold
                uint64_t start_time = thread_states_[i].enter_timestamp.load(std::memory_order_acquire);
                if ((now - start_time) > EPOCH_PIN_TIMEOUT_CYCLES) {
                    // Reader stall detected: rely on Hazard Pointer fallback
                    continue; 
                }
                return; // Normal active reader in old epoch prevents advancement
            }
        }
        global_epoch_.fetch_add(1, std::memory_order_acq_rel);
    }

    void reclaim_quarantine(size_t tid) {
        uint64_t cur = global_epoch_.load(std::memory_order_acquire);
        if (cur < 2) return;

        // Reclamation target is (cur - 2)
        uint64_t safe_epoch = cur - 2;
        auto& bag = retired_bags_[tid][safe_epoch % 3];

        auto it = bag.begin();
        while (it != bag.end()) {
            VersionNode* node = *it;
            if (is_hazard_protected(node)) {
                ++it; // Skip nodes actively tracked by emergency Hazard Pointers
            } else {
                delete node;
                it = bag.erase(it);
            }
        }
    }

private:
    AdaptiveEpochManager() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            for (size_t e = 0; e < 3; ++e) {
                retired_bags_[i][e].reserve(1024);
            }
        }
    }

    bool is_hazard_protected(const void* ptr) const noexcept {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (thread_states_[i].active.load(std::memory_order_relaxed) &&
                thread_states_[i].hazard_ptr.load(std::memory_order_acquire) == ptr) {
                return true;
            }
        }
        return false;
    }

    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> global_epoch_{0};
    alignas(CACHE_LINE_SIZE) std::array<ThreadEpochState, MAX_THREADS> thread_states_{};
    std::vector<VersionNode*> retired_bags_[MAX_THREADS][3];
};

} // namespace mvcc
