## Part 1: Lock-Free MVCC Index & Stall-Resilient Memory Lifecycle

### 1. Data Structures & Memory Layout

```cpp
#pragma once

#include <atomic>
#include <cstdint>
#include <cstddef>
#include <cstring>
#include <memory>
#include <array>
#include <limits>
#include <optional>
#include <new>

// Ensure cache line isolation to prevent false sharing under high concurrency
inline constexpr size_t CACHE_LINE_SIZE = 64;
inline constexpr size_t MAX_SKIPLIST_LEVELS = 24;
inline constexpr uint64_t INF_TS = std::numeric_limits<uint64_t>::max();
inline constexpr uint64_t TX_ACTIVE = std::numeric_limits<uint64_t>::max() - 1;
inline constexpr uint64_t TX_ABORTED = std::numeric_limits<uint64_t>::max() - 2;

// Atomic tagged pointer representation for lock-free logical deletion
template <typename T>
struct MarkedPtr {
    static constexpr uintptr_t MARK_MASK = 0x1;

    static T* get_ptr(T* ptr) noexcept {
        return reinterpret_cast<T*>(reinterpret_cast<uintptr_t>(ptr) & ~MARK_MASK);
    }

    static bool is_marked(T* ptr) noexcept {
        return (reinterpret_cast<uintptr_t>(ptr) & MARK_MASK) != 0;
    }

    static T* set_mark(T* ptr) noexcept {
        return reinterpret_cast<T*>(reinterpret_cast<uintptr_t>(ptr) | MARK_MASK);
    }

    static T* clean_mark(T* ptr) noexcept {
        return reinterpret_cast<T*>(reinterpret_cast<uintptr_t>(ptr) & ~MARK_MASK);
    }
};

// MVCC Version Record Node
struct alignas(CACHE_LINE_SIZE) VersionNode {
    uint64_t tx_id;                      // Transaction ID that created this version
    std::atomic<uint64_t> commit_ts;     // Timestamp at commit; TX_ACTIVE or TX_ABORTED if unresolved
    bool deleted_flag;                   // Tombstone marker for SI deletes
    uint32_t val_len;                    // Length of stored payload
    std::atomic<VersionNode*> next_version{nullptr}; // Descending chronological chain
    alignas(16) char value_payload[0];   // Flexible array member for zero-overhead payload

    static VersionNode* create(uint64_t tx_id, uint64_t commit_ts, bool deleted, 
                              const void* data, uint32_t len) {
        size_t total_size = sizeof(VersionNode) + len;
        void* raw_mem = ::operator new(total_size, std::align_val_t{alignof(VersionNode)});
        auto* node = new (raw_mem) VersionNode();
        node->tx_id = tx_id;
        node->commit_ts.store(commit_ts, std::memory_order_relaxed);
        node->deleted_flag = deleted;
        node->val_len = len;
        node->next_version.store(nullptr, std::memory_order_relaxed);
        if (len > 0 && data != nullptr) {
            std::memcpy(node->value_payload, data, len);
        }
        return node;
    }

    static void destroy(VersionNode* node) noexcept {
        if (!node) return;
        node->~VersionNode();
        ::operator delete(node, std::align_val_t{alignof(VersionNode)});
    }
};

// Multi-Level Lock-Free Skip-List Node
template <typename Key>
struct alignas(CACHE_LINE_SIZE) SkipNode {
    Key key;
    uint32_t height;
    std::atomic<VersionNode*> version_head{nullptr};

    // Tower of forward pointers for Harris-style lock-free skip-list traversal
    struct ForwardLink {
        std::atomic<SkipNode<Key>*> next{nullptr};
    };

    // Flexible array for forward pointers depending on height
    ForwardLink forward[0];

    static SkipNode* create(const Key& key, uint32_t height) {
        size_t total_size = sizeof(SkipNode) + (height * sizeof(ForwardLink));
        void* raw_mem = ::operator new(total_size, std::align_val_t{alignof(SkipNode)});
        auto* node = new (raw_mem) SkipNode();
        node->key = key;
        node->height = height;
        node->version_head.store(nullptr, std::memory_order_relaxed);
        for (uint32_t i = 0; i < height; ++i) {
            node->forward[i].next.store(nullptr, std::memory_order_relaxed);
        }
        return node;
    }

    static void destroy(SkipNode* node) noexcept {
        if (!node) return;
        node->~SkipNode();
        ::operator delete(node, std::align_val_t{alignof(SkipNode)});
    }
};
