## Part 3: Complete Transaction Engine Execution Loop

```cpp
#include <iostream>
#include <chrono>

class MVCCStorageKernel {
private:
    LockFreeMVCCSkipList<uint64_t> index_;
    LockFreeMPSCWALRing wal_ring_;
    AsyncIOUringWALEngine wal_engine_;
    std::atomic<uint64_t> global_lsn_{1};
    std::atomic<uint64_t> global_ts_{1};

public:
    MVCCStorageKernel(const char* wal_path)
        : wal_engine_(wal_path, wal_ring_) {
        wal_engine_.start();
    }

    ~MVCCStorageKernel() {
        wal_engine_.stop();
    }

    uint64_t begin_transaction() {
        return global_ts_.fetch_add(1, std::memory_order_relaxed);
    }

    std::optional<std::string> read(uint64_t key, uint64_t read_ts) {
        return index_.search(key, read_ts);
    }

    bool write_and_commit(uint64_t key, const std::string& val, uint64_t tx_id) {
        // 1. Stage in lock-free MVCC index as TX_ACTIVE
        if (!index_.upsert(key, val.data(), val.size(), tx_id)) {
            return false; // WW conflict -> Abort
        }

        // 2. Assign LSN & Commit Timestamp
        uint64_t lsn = global_lsn_.fetch_add(1, std::memory_order_relaxed);
        uint64_t commit_ts = global_ts_.fetch_add(1, std::memory_order_relaxed);

        // 3. Emit WAL Record to Lock-Free MPSC Ring
        uint64_t allocated_slot = 0;
        while (!wal_ring_.enqueue(lsn, tx_id, &key, sizeof(key), val.data(), val.size(), allocated_slot)) {
            _mm_pause(); // Ring full: backoff
        }

        // 4. Await durable disk persistence via io_uring group commit
        wal_engine_.await_lsn_durable(lsn);

        // 5. Mark index version as committed
        index_.commit_version(key, tx_id, commit_ts);
        return true;
    }
};
